-- Reviewed catalog batch 20261016: Korean titles for Japanese-only titles;
-- English/mixed titles remain unchanged; add reviewed Korean search aliases.
-- Execute the entire file on one schema-owner connection. Conflicts roll back all changes.
BEGIN;
SET LOCAL lock_timeout = '5s';
SET LOCAL statement_timeout = '30s';
CREATE TEMP TABLE desired_song_alias (
  song_id uuid, expected_title text, expected_version bigint,
  new_title text, new_search_title text, alias text, search_alias text,
  PRIMARY KEY(song_id, search_alias)
) ON COMMIT DROP;
SELECT s.id FROM app.song_entry s
WHERE s.id IN (SELECT song_id FROM desired_song_alias) ORDER BY s.id FOR UPDATE;
DO $$
BEGIN
  IF EXISTS (
    SELECT 1 FROM desired_song_alias d LEFT JOIN app.song_entry s ON s.id=d.song_id
    WHERE (s.id IS NULL OR s.title<>d.new_title OR NOT EXISTS (
      SELECT 1 FROM app.song_alias a WHERE a.song_id=d.song_id AND a.search_alias=d.search_alias))
      AND (s.id IS NULL OR s.title<>d.expected_title OR s.version<>d.expected_version)
  ) THEN RAISE EXCEPTION 'Catalog batch conflict: review current song title/version'; END IF;
END $$;
CREATE TEMP TABLE alias_batch_before ON COMMIT DROP AS
SELECT s.id, jsonb_build_object('id',s.id,'title',s.title,'version',s.version,
  'aliases',COALESCE((SELECT jsonb_agg(a.alias ORDER BY a.search_alias) FROM app.song_alias a WHERE a.song_id=s.id),'[]'::jsonb)) AS before_value
FROM app.song_entry s WHERE EXISTS (
  SELECT 1 FROM desired_song_alias d WHERE d.song_id=s.id AND (s.title<>d.new_title OR NOT EXISTS (
    SELECT 1 FROM app.song_alias a WHERE a.song_id=d.song_id AND a.search_alias=d.search_alias)));
SELECT song_id,alias,search_alias FROM desired_song_alias ON CONFLICT(song_id,search_alias) DO NOTHING;
-- This UPDATE cannot target English or mixed titles: only reviewed Japanese-only title changes.
UPDATE app.song_entry s SET title=d.new_title,search_title=d.new_search_title
FROM (SELECT DISTINCT song_id,expected_title,new_title,new_search_title FROM desired_song_alias
      WHERE expected_title<>new_title) d WHERE s.id=d.song_id AND s.title<>d.new_title;
UPDATE app.song_entry s SET version=version+1,edited_at=CURRENT_TIMESTAMP
FROM alias_batch_before b WHERE b.id=s.id;
SELECT gen_random_uuid(),'SONGS',s.id,'UPDATE',b.before_value,
  jsonb_build_object('id',s.id,'title',s.title,'version',s.version,
    'aliases',(SELECT jsonb_agg(a.alias ORDER BY a.search_alias) FROM app.song_alias a WHERE a.song_id=s.id)),
  'song-search-aliases-20261016: 일본어 제목 한국어 표기 및 검토한 검색 별칭 보완; 영어 제목 유지'
FROM app.song_entry s JOIN alias_batch_before b ON b.id=s.id;
SELECT (SELECT count(*) FROM alias_batch_before) AS changed_songs,
       (SELECT count(*) FROM alias_batch_before WHERE before_value->>'title'<>
         (SELECT title FROM app.song_entry WHERE id=alias_batch_before.id)) AS renamed_songs,
       (SELECT count(*) FROM desired_song_alias) AS verified_aliases;
COMMIT;
